<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,watch,nextTick} from 'vue';
import {request,ApiError} from '../lib/api';
import {beadPalette,beadProgress,beadLine,beadFill,resizePattern,quantizeBeads,paintBeads,exportBeads,validBeadData,type BeadWork} from '../lib/beads';
import {beadPatterns} from '../lib/bead-patterns';
import BeadThumbnail from './BeadThumbnail.vue';
const props=defineProps<{accountId:string;foreground:boolean}>();const emit=defineEmits<{(e:'auth-expired'):void}>();
const project=ref<BeadWork|null>(null),canvas=ref<HTMLCanvasElement|null>(null),viewport=ref<HTMLElement|null>(null),fileInput=ref<HTMLInputElement|null>(null),cropCanvas=ref<HTMLCanvasElement|null>(null);
const selected=ref(4),tool=ref('pen'),zoom=ref(1),guide=ref(true),sound=ref(false),dirty=ref(false),saving=ref(false),conflict=ref(false),saveState=ref(''),error=ref(''),notice=ref(''),melting=ref(false);
const undoStack=ref<number[][]>([]),redoStack=ref<number[][]>([]);
const dialog=ref<''|'new'|'image'|'library'|'delete'|'clear'>(''),createSize=ref(16),library=ref<BeadWork[]>([]),libraryPage=ref(1),libraryTotal=ref(0),libraryBusy=ref(false),deleteTarget=ref<BeadWork|null>(null),deleting=ref(false);
const importLoaded=ref(false),importBusy=ref(false),importName=ref(''),maxColors=ref(16),cropZoom=ref(1),cropX=ref(50),cropY=ref(50),converted=ref<number[]>([]);
let image:HTMLImageElement|null=null,imageURL='',imageSequence=0,disposed=false,changes=0,saveTimer:ReturnType<typeof setTimeout>|undefined,meltTimer:ReturnType<typeof setTimeout>|undefined,savePromise:Promise<boolean>|undefined,frame=0;
let pointer:number|null=null,strokeBefore:number[]|null=null,lastCell:number|null=null,lastPoint={x:0,y:0},audio:AudioContext|null=null,lastSound=0;
const storageKey='mind-offline-beads-draft:'+props.accountId;
const progress=computed(()=>project.value?beadProgress(project.value.data):{filled:0,total:0,correct:0,extra:0,complete:false});
const counts=computed(()=>{const d=project.value?.data;return beadPalette.map((_,color)=>({color,placed:d?.pixels.filter(v=>v===color).length||0,left:d?.mode==='guided'?d.target.filter((v,i)=>v===color&&v!==d.pixels[i]).length:0}));});
const boardSide=computed(()=>(project.value?.data.size||16)*20*zoom.value);
const percent=computed(()=>progress.value.total?Math.round(progress.value.correct/progress.value.total*100):0);
function fail(e:unknown){if(disposed)return;if(e instanceof ApiError&&e.status===401)emit('auth-expired');if(!(e instanceof ApiError&&e.status===0))error.value=(e as Error).message;}
function draft(){if(!project.value)return;try{localStorage.setItem(storageKey,JSON.stringify({work:{...project.value,data:{...project.value.data,name:project.value.data.name.trim()||'未命名拼豆'}},dirty:dirty.value}));}catch{notice.value='本机草稿空间不足，请及时保存到作品库。';}}
function changed(){changes++;dirty.value=true;saveState.value='草稿已暂存';draft();clearTimeout(saveTimer);if(!conflict.value)saveTimer=setTimeout(()=>void save(),1600);invalidate();}
function save():Promise<boolean>{if(savePromise)return savePromise;if(!project.value||!dirty.value)return Promise.resolve(true);if(conflict.value)return Promise.resolve(false);clearTimeout(saveTimer);const work=JSON.parse(JSON.stringify(project.value)) as BeadWork;work.data.name=work.data.name.trim()||'未命名拼豆';const version=changes;saving.value=true;saveState.value='正在保存…';
 savePromise=(async()=>{try{const saved=await request<BeadWork>('/beads','POST',{id:work.id,revision:work.revision,data:work.data});if(disposed)return false;if(project.value?.id===work.id){project.value.revision=saved.revision;project.value.updated_at=saved.updated_at;dirty.value=changes!==version;saveState.value=dirty.value?'还有新改动待保存':'已保存到我的作品';error.value='';draft();}return true;}catch(e){if(!disposed){conflict.value=e instanceof ApiError&&e.status===409;saveState.value='云端未保存 · 本机草稿保留';fail(e);}return false;}finally{saving.value=false;savePromise=undefined;}})();return savePromise.then(ok=>{if(ok&&dirty.value&&!disposed)saveTimer=setTimeout(()=>void save(),800);return ok;});}
async function manualSave(){conflict.value=false;await save();}
async function beforeSwitch(){finishStroke();if(melting.value)return false;if(dirty.value||saving.value){if(!await save()||dirty.value)return false;}return true;}
async function copyWork(){if(!project.value||saving.value||melting.value)return;project.value={...JSON.parse(JSON.stringify(project.value)),id:crypto.randomUUID(),revision:0};project.value!.data.name=(project.value!.data.name.slice(0,32)+' · 副本');conflict.value=false;changed();await save();}
function resetHistory(){undoStack.value=[];redoStack.value=[];tool.value='pen';guide.value=true;conflict.value=false;notice.value='今天不拼业绩，拼点自己喜欢的。';}
async function create(name:string,mode:'guided'|'free',pattern?:number[]){if(!await beforeSwitch())return;project.value={id:crypto.randomUUID(),revision:0,data:{name,size:createSize.value,mode,pixels:mode==='guided'?Array(createSize.value**2).fill(0):(pattern?.slice()||Array(createSize.value**2).fill(0)),target:mode==='guided'?pattern!.slice():[],finished:false}};resetHistory();dialog.value='';changed();await fit();}
async function choosePattern(index:number){const p=beadPatterns[index];await create(p.name,'guided',resizePattern(p.pixels,16,createSize.value));}
async function openWork(w:BeadWork){if(!await beforeSwitch())return;error.value='';try{const fresh=await request<BeadWork>('/beads/'+w.id);if(disposed)return;project.value=fresh;dirty.value=false;saveState.value='已打开云端作品';resetHistory();dialog.value='';draft();await fit();}catch(e){fail(e);}}
async function loadLibrary(page=1){if(libraryBusy.value)return;libraryBusy.value=true;error.value='';try{const data=await request<{items:BeadWork[];total:number}>('/beads?page='+page);if(disposed)return;library.value=data.items;libraryPage.value=page;libraryTotal.value=data.total;}catch(e){fail(e);}finally{libraryBusy.value=false;}}
function showLibrary(){dialog.value='library';void loadLibrary();}
function askDelete(w:BeadWork){deleteTarget.value=w;dialog.value='delete';}
async function deleteWork(){const w=deleteTarget.value;if(!w||deleting.value||saving.value)return;if(project.value?.id===w.id&&!await beforeSwitch())return;deleting.value=true;try{await request('/beads/'+w.id+'/delete','POST',{revision:project.value?.id===w.id?project.value.revision:w.revision});if(disposed)return;if(project.value?.id===w.id){project.value=null;dirty.value=false;clearTimeout(saveTimer);localStorage.removeItem(storageKey);}dialog.value='library';await loadLibrary(libraryPage.value);}catch(e){fail(e);}finally{deleting.value=false;}}
function pushHistory(previous:number[]){undoStack.value.push(previous);if(undoStack.value.length>60)undoStack.value.shift();redoStack.value=[];}
function undo(){if(!project.value||!undoStack.value.length||melting.value)return;redoStack.value.push(project.value.data.pixels.slice());project.value.data.pixels=undoStack.value.pop()!;project.value.data.finished=false;changed();notice.value='这颗不算，刚才是老板碰的。';}
function redo(){if(!project.value||!redoStack.value.length||melting.value)return;undoStack.value.push(project.value.data.pixels.slice());project.value.data.pixels=redoStack.value.pop()!;project.value.data.finished=false;changed();}
function clearBoard(){if(!project.value||melting.value)return;pushHistory(project.value.data.pixels.slice());project.value.data.pixels=Array(project.value.data.size**2).fill(0);project.value.data.finished=false;dialog.value='';changed();}
function invalidate(){if(disposed)return;cancelAnimationFrame(frame);frame=requestAnimationFrame(draw);}
function draw(){const c=canvas.value,d=project.value?.data;if(!c||!d)return;const side=d.size*20,ratio=Math.min(window.devicePixelRatio||1,2);c.width=c.height=side*ratio;const ctx=c.getContext('2d')!;ctx.scale(ratio,ratio);ctx.fillStyle='#f7f5e9';ctx.fillRect(0,0,side,side);if(d.mode==='guided'&&guide.value&&!d.finished){ctx.globalAlpha=.22;paintBeads(ctx,d.target,d.size,20,true);ctx.globalAlpha=1;}paintBeads(ctx,d.pixels,d.size,20,!d.finished);if(d.mode==='guided'&&guide.value&&!d.finished){for(let i=0;i<d.pixels.length;i++){const x=i%d.size*20,y=Math.floor(i/d.size)*20;if(d.target[i]===selected.value&&d.pixels[i]!==d.target[i]){ctx.strokeStyle='#8b9b69';ctx.lineWidth=1;ctx.strokeRect(x+2,y+2,16,16);}if(d.pixels[i]&&d.pixels[i]!==d.target[i]){ctx.strokeStyle='#d17d73';ctx.lineWidth=2;ctx.strokeRect(x+2,y+2,16,16);}}}}
async function fit(){await nextTick();if(!project.value||!viewport.value)return;zoom.value=Math.max(.3,Math.min(1,(viewport.value.clientWidth-30)/(project.value.data.size*20)));invalidate();}
function cellAt(e:PointerEvent){const c=canvas.value,d=project.value?.data;if(!c||!d)return null;const r=c.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)/r.width*d.size),y=Math.floor((e.clientY-r.top)/r.height*d.size);return x<0||y<0||x>=d.size||y>=d.size?null:y*d.size+x;}
function selectColor(c:number){selected.value=c;if(tool.value!=='fill')tool.value='pen';}
function tick(){if(!sound.value||Date.now()-lastSound<60)return;lastSound=Date.now();try{audio=audio||new AudioContext();void audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.setValueAtTime(620,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(210,audio.currentTime+.03);gain.gain.setValueAtTime(.035,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.035);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.04);}catch{sound.value=false;}}
function place(i:number){const d=project.value!.data,color=tool.value==='erase'?0:selected.value;if(d.pixels[i]!==color){d.pixels[i]=color;tick();}}
function pointerDown(e:PointerEvent){if(!project.value||melting.value||e.button!==0||!e.isPrimary)return;if(project.value.data.finished){notice.value='这是熨好的成品，点“继续编辑”还能改。';return;}pointer=e.pointerId;canvas.value?.setPointerCapture(e.pointerId);lastPoint={x:e.clientX,y:e.clientY};if(tool.value==='move')return;const i=cellAt(e);if(i===null)return;if(tool.value==='pick'){const color=project.value.data.pixels[i]||project.value.data.target[i];if(color)selected.value=color;tool.value='pen';invalidate();return;}if(tool.value==='fill'&&project.value.data.mode==='free'){const before=project.value.data.pixels.slice(),after=beadFill(before,project.value.data.size,i,selected.value);if(after.some((v,k)=>v!==before[k])){pushHistory(before);project.value.data.pixels=after;changed();tick();}return;}strokeBefore=project.value.data.pixels.slice();lastCell=i;place(i);invalidate();}
function pointerMove(e:PointerEvent){if(e.pointerId!==pointer||!project.value)return;if(tool.value==='move'){if(viewport.value){viewport.value.scrollLeft-=e.clientX-lastPoint.x;viewport.value.scrollTop-=e.clientY-lastPoint.y;}lastPoint={x:e.clientX,y:e.clientY};return;}if(!strokeBefore)return;const i=cellAt(e);if(i===null){lastCell=null;return;}for(const cell of lastCell===null?[i]:beadLine(lastCell,i,project.value.data.size))place(cell);lastCell=i;invalidate();}
function finishStroke(){if(strokeBefore&&project.value&&strokeBefore.some((v,i)=>v!==project.value!.data.pixels[i])){pushHistory(strokeBefore);changed();if(progress.value.complete&&project.value.data.mode==='guided')notice.value='豆子到齐，随时可以熨出你的成品。';}strokeBefore=null;lastCell=null;pointer=null;}
function finish(){if(!project.value||!progress.value.complete||melting.value)return;melting.value=true;notice.value='正在熨平内耗，请稍候…';meltTimer=setTimeout(()=>{if(disposed||!project.value)return;project.value.data.finished=true;melting.value=false;changed();notice.value='作品已出炉，建议计入今日有效产出。';},1300);}
function editAgain(){if(project.value){project.value.data.finished=false;changed();}}
async function chooseImage(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;const seq=++imageSequence;importBusy.value=true;error.value='';try{if(file.size>10*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('请选择10MB以内的 JPG、PNG 或 WebP 图片。');const url=URL.createObjectURL(file),img=new Image();try{img.src=url;await img.decode();if(disposed||seq!==imageSequence){URL.revokeObjectURL(url);return;}if(img.naturalWidth*img.naturalHeight>25000000)throw new Error('图片太大，请缩小到2500万像素以内再试。');if(imageURL)URL.revokeObjectURL(imageURL);imageURL=url;image=img;importName.value=file.name.replace(/\.[^.]+$/,'').slice(0,32)||'照片拼豆';cropZoom.value=1;cropX.value=cropY.value=50;importLoaded.value=true;await nextTick();convertImage();}catch(err){URL.revokeObjectURL(url);throw err;}}catch(err){fail(err);}finally{if(!disposed&&seq===imageSequence)importBusy.value=false;}}
function convertImage(){if(!image||!importLoaded.value)return;const side=Math.min(image.naturalWidth,image.naturalHeight)/Number(cropZoom.value),x=(image.naturalWidth-side)*Number(cropX.value)/100,y=(image.naturalHeight-side)*Number(cropY.value)/100;const c=document.createElement('canvas');c.width=c.height=createSize.value;const ctx=c.getContext('2d')!;ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(image,x,y,side,side,0,0,c.width,c.height);converted.value=quantizeBeads(ctx.getImageData(0,0,c.width,c.height).data,Number(maxColors.value));const preview=cropCanvas.value;if(preview){preview.width=preview.height=240;preview.getContext('2d')!.drawImage(image,x,y,side,side,0,0,240,240);}}
async function imageProject(mode:'free'|'guided'){if(!converted.value.some(Boolean)){error.value='这张图没有可见像素，换张图片试试。';return;}await create(importName.value,mode,converted.value);if(!dialog.value){image=null;if(imageURL)URL.revokeObjectURL(imageURL);imageURL='';importLoaded.value=false;converted.value=[];}}
watch([createSize,maxColors,cropZoom,cropX,cropY],()=>{if(dialog.value==='image')convertImage();});
watch(selected,invalidate);watch(()=>props.foreground,async v=>{if(v){await nextTick();invalidate();}else{finishStroke();draft();void save();}});
function beforeUnload(e:BeforeUnloadEvent){finishStroke();draft();if(dirty.value){e.preventDefault();e.returnValue='';}}
function keyboard(e:KeyboardEvent){if(!props.foreground||dialog.value||['INPUT','TEXTAREA','SELECT'].includes((e.target as HTMLElement)?.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();void manualSave();}}
function closeDialog(){if(!deleting.value&&!importBusy.value){dialog.value='';error.value='';}}
let modalFocus:HTMLElement|null=null;
watch(dialog,async(value,old)=>{if(value&&!old)modalFocus=document.activeElement as HTMLElement;await nextTick();if(value)document.getElementById('bead-dialog-close')?.focus();else modalFocus?.focus();if(value==='image')convertImage();});
function dialogKeys(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();closeDialog();}if(e.key==='Tab'){const els=Array.from(document.querySelectorAll<HTMLElement>('#bead-dialog button:not([disabled]),#bead-dialog uni-button:not([disabled]),#bead-dialog input:not([disabled]):not([type=file]),#bead-dialog select'));const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);window.addEventListener('keydown',keyboard);try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved&&typeof saved.work?.id==='string'&&Number.isInteger(saved.work.revision)&&saved.work.revision>=0&&validBeadData(saved.work.data)){project.value=saved.work;dirty.value=!!saved.dirty;notice.value='上次的豆子还在，接着慢慢拼。';if(!dirty.value&&saved.work.revision>0){try{const fresh=await request<BeadWork>('/beads/'+saved.work.id);if(disposed)return;project.value=fresh;}catch(e){if(e instanceof ApiError&&e.status===404){dirty.value=true;conflict.value=true;}else fail(e);}}if(disposed)return;await fit();if(dirty.value&&!conflict.value)void save();}}catch{notice.value='本机草稿无法恢复，仍可从“我的作品”打开云端记录。';}});
onBeforeUnmount(()=>{finishStroke();draft();disposed=true;imageSequence++;clearTimeout(saveTimer);clearTimeout(meltTimer);cancelAnimationFrame(frame);if(imageURL)URL.revokeObjectURL(imageURL);void audio?.close();window.removeEventListener('beforeunload',beforeUnload);window.removeEventListener('keydown',keyboard);});
</script>
<template><view class="bead-studio">
<view class="bead-hero"><view><text class="eyebrow">带薪游乐场 / 单人试营业</text><text class="title">电子拼豆 <text>✿</text></text><text class="subtitle">今天不拼业绩，拼点自己喜欢的。</text></view><view class="hero-tools"><button :disabled="melting" @click="dialog='new'">＋ 新作品</button><button @click="showLibrary">我的作品 ↗</button></view></view>
<text v-if="error" class="bead-error" role="alert">{{error}}</text>
<view v-if="!project" class="start-screen"><view class="intro-card"><text class="intro-face">( •ᴗ• )</text><text class="section">把散落的快乐，一颗颗拼回来。</text><text class="hint">鼠标点一点，手指戳一戳。不计时，不排名，拼到一半也能下班。</text><view class="start-actions"><button class="primary" @click="dialog='new'">挑个图案开拼</button><button @click="create('我的自由拼豆','free')">自由拼 · {{createSize}}格</button><button @click="dialog='image'">照片变拼豆</button></view></view><view class="template-grid"><button v-for="(p,i) in beadPatterns" :key="p.name" class="pattern-card" @click="choosePattern(i)"><BeadThumbnail :pixels="p.pixels" :size="16"/><text>{{p.name}}</text><text class="hint">{{p.note}}</text></button></view></view>
<template v-else><view class="work-heading"><component :is="'input'" class="work-name" :value="project.data.name" maxlength="40" aria-label="作品名称，可以重命名" @input="project.data.name=$event.target.value;changed()"/><view><text class="save-state">{{saving?'正在保存…':saveState||'本机草稿'}}</text><button :disabled="saving||melting" @click="manualSave">保存</button></view></view><view v-if="conflict" class="conflict"><text>{{error||'云端版本已变化，本页草稿保留。'}}</text><button :disabled="saving" @click="copyWork">另存一份</button><button @click="showLibrary">整理作品库</button></view>
<view class="editor-layout"><view class="board-card"><view class="tool-row"><button v-for="t in [{id:'pen',name:'● 放豆'},{id:'erase',name:'⌫ 橡皮'},{id:'pick',name:'◉ 吸色'},{id:'move',name:'✥ 移动画布'}]" :key="t.id" :class="{selected:tool===t.id}" :disabled="melting||project.data.finished" @click="tool=t.id">{{t.name}}</button><button v-if="project.data.mode==='free'" :class="{selected:tool==='fill'}" :disabled="melting||project.data.finished" @click="tool='fill'">▧ 填充</button><button :disabled="!undoStack.length||melting" @click="undo">↶ 撤销</button><button :disabled="!redoStack.length||melting" @click="redo">↷ 重做</button></view>
<component :is="'div'" ref="viewport" class="board-viewport"><view class="board-inner" :style="{width:boardSide+'px',height:boardSide+'px'}"><component :is="'canvas'" ref="canvas" class="bead-canvas" :style="{width:boardSide+'px',height:boardSide+'px',cursor:tool==='move'?'grab':'crosshair'}" aria-label="拼豆画板，按住拖动放豆，移动工具拖动画布" @pointerdown="pointerDown" @pointermove="pointerMove" @pointerup="finishStroke" @pointercancel="finishStroke" @lostpointercapture="finishStroke"/><view v-if="melting" class="iron-overlay"><view class="iron">♨</view><text>正在熨平内耗…</text></view></view></component>
<view class="board-controls"><button @click="zoom=Math.max(.3,zoom-.15)">−</button><text>{{Math.round(zoom*100)}}%</text><button @click="zoom=Math.min(2.5,zoom+.15)">＋</button><button @click="fit">适合屏幕</button><button @click="sound=!sound">{{sound?'♪ 音效开':'♪ 音效关'}}</button><button v-if="project.data.mode==='guided'" @click="guide=!guide;invalidate()">{{guide?'✓ 辅助开':'辅助关'}}</button></view><text class="hint">按住拖动连续放豆；手机用“移动画布”拖动，用 ＋ / − 缩放。名称可直接修改。</text><text class="quip" role="status">{{notice}}</text></view>
<view class="palette-card"><view v-if="project.data.mode==='guided'" class="reference"><BeadThumbnail :pixels="project.data.target" :size="project.data.size"/><view><text class="section">照着拼</text><text class="hint">绿色框：选中色的位置<br/>红色框：放错的位置</text></view></view><view class="progress-copy"><text>{{project.data.mode==='guided'?'已拼 '+progress.correct+' / '+progress.total:'已经放下 '+progress.filled+' 颗豆子'}}</text><text v-if="project.data.mode==='guided'">{{percent}}%</text></view><view v-if="project.data.mode==='guided'" class="progress-track"><view :style="{width:percent+'%'}"/></view><text v-if="progress.extra" class="hint">空白位置还多放了 {{progress.extra}} 颗，可以用橡皮移除。</text>
<text class="section palette-title">今天用什么颜色？</text><view class="palette"><button v-for="(hex,i) in beadPalette.slice(1)" :key="hex" :class="['swatch',{chosen:selected===i+1}]" :style="{background:hex}" :aria-label="(i+1)+'号颜色 '+hex" :aria-pressed="selected===i+1" @click="selectColor(i+1)"><text v-if="selected===i+1">✓</text></button></view><view class="color-caption"><view :style="{background:beadPalette[selected]}"/><text>{{selected}}号 · 已放 {{counts[selected].placed}} 颗<text v-if="project.data.mode==='guided'"> / 还差 {{counts[selected].left}} 颗</text></text></view><text class="hint">基础创作色板，不是实物品牌色号。</text>
<button v-if="!project.data.finished" class="primary finish" :disabled="!progress.complete||melting" @click="finish">{{melting?'正在熨烫…':'拼完了，熨一下 ♨'}}</button><button v-else class="primary finish" @click="editAgain">继续编辑 · 豆子还能改</button><text v-if="project.data.mode==='guided'&&!progress.complete" class="hint">按参考图放好每颗豆子，就可以熨出成品。</text><view class="export-actions"><button :disabled="!progress.filled||melting" @click="exportBeads(project.data)">↓ 成品 PNG</button><button :disabled="!progress.filled||melting" @click="exportBeads(project.data,true)">↓ 网格图纸</button></view><button class="clear-link" :disabled="!progress.filled||melting" @click="dialog='clear'">清空画板</button></view></view></template>
<view v-if="project && foreground && !dialog && !project.data.finished && !melting" class="mobile-color-dock"><text>{{selected}}号</text><view class="dock-colors"><button v-for="(hex,i) in beadPalette.slice(1)" :key="hex" :class="['swatch',{chosen:selected===i+1}]" :style="{background:hex}" :aria-label="'选择'+(i+1)+'号颜色'" @click="selectColor(i+1)"><text v-if="selected===i+1">✓</text></button></view><button class="dock-move" @click="tool=tool==='move'?'pen':'move'">{{tool==='move'?'放豆':'移动'}}</button></view>
<view v-if="dialog" class="bead-backdrop" @click.self="closeDialog" @keydown="dialogKeys"><view id="bead-dialog" class="bead-dialog" role="dialog" aria-modal="true" aria-labelledby="bead-dialog-title"><view class="dialog-heading"><view><text class="eyebrow">你的私人拼豆工作台</text><text id="bead-dialog-title" class="section">{{dialog==='library'?'我的作品':dialog==='image'?'照片变拼豆':dialog==='delete'?'收走这件作品？':dialog==='clear'?'清空这块底板？':'今天想拼点什么？'}}</text></view><button id="bead-dialog-close" tabindex="0" :disabled="deleting||importBusy" @click="closeDialog" aria-label="关闭">×</button></view><text v-if="error" class="bead-error" role="alert">{{error}}</text>
<template v-if="dialog==='new'||dialog==='image'"><view class="size-options"><text>画布</text><button v-for="n in [16,32,48]" :key="n" :class="{selected:createSize===n}" @click="createSize=n">{{n}} × {{n}}</button></view></template>
<template v-if="dialog==='new'"><view class="start-actions"><button class="primary" :disabled="saving" @click="create('我的自由拼豆','free')">空白底板 · 自由拼</button><button @click="dialog='image'">导入自己的图片</button></view><view class="template-grid"><button v-for="(p,i) in beadPatterns" :key="p.name" class="pattern-card" :disabled="saving" @click="choosePattern(i)"><BeadThumbnail :pixels="p.pixels" :size="16"/><text>{{p.name}}</text><text class="hint">{{p.note}}</text></button></view></template>
<template v-else-if="dialog==='image'"><component :is="'input'" ref="fileInput" type="file" accept="image/jpeg,image/png,image/webp" class="file-input" @change="chooseImage"/><button class="primary" :disabled="importBusy" @click="fileInput?.click()">{{importBusy?'正在读取图片…':importLoaded?'换张图片':'选择图片'}}</button><text class="hint">图片只在浏览器里转换，不上传原图。支持10MB以内 JPG / PNG / WebP；头像和卡通图更适合小画布。</text><template v-if="importLoaded"><view class="import-previews"><view><component :is="'canvas'" ref="cropCanvas" class="crop-preview"/><text>裁剪区域</text></view><view><BeadThumbnail :pixels="converted" :size="createSize"/><text>拼豆预览</text></view></view><view class="crop-settings"><label>裁剪放大 <component :is="'input'" type="range" min="1" max="3" step="0.1" :value="cropZoom" @input="cropZoom=Number($event.target.value)"/></label><label>左右移动 <component :is="'input'" type="range" min="0" max="100" :value="cropX" @input="cropX=Number($event.target.value)"/></label><label>上下移动 <component :is="'input'" type="range" min="0" max="100" :value="cropY" @input="cropY=Number($event.target.value)"/></label></view><view class="size-options"><text>最多颜色</text><button v-for="n in [8,16,24,32]" :key="n" :class="{selected:maxColors===n}" @click="maxColors=n">{{n}}色</button></view><view class="start-actions"><button class="primary" :disabled="saving||importBusy" @click="imageProject('guided')">生成底稿，亲手拼</button><button :disabled="saving||importBusy" @click="imageProject('free')">直接编辑生成图</button></view></template></template>
<template v-else-if="dialog==='library'"><text class="hint">仅自己可见 · {{libraryTotal}} / 100 件 · 按最近保存排列</text><view v-if="!library.length" class="empty">{{libraryBusy?'正在翻作品箱…':'作品箱还是空的，先拼一件吧。'}}</view><view class="library-grid"><view v-for="w in library" :key="w.id" class="library-work"><BeadThumbnail :pixels="w.data.pixels" :size="w.data.size" :round="!w.data.finished"/><text class="work-card-name">{{w.data.name}}</text><text class="hint">{{w.data.size}}格 · {{w.data.finished?'已熨好':w.data.mode==='guided'?'照着拼':'自由创作'}}</text><view><button :disabled="saving" @click="openWork(w)">继续拼</button><button class="delete-link" :disabled="saving" @click="askDelete(w)">删除</button></view></view></view><view class="pager"><button :disabled="libraryPage===1||libraryBusy" @click="loadLibrary(libraryPage-1)">上一页</button><text>{{libraryPage}} / {{Math.max(1,Math.ceil(libraryTotal/12))}}</text><button :disabled="libraryPage*12>=libraryTotal||libraryBusy" @click="loadLibrary(libraryPage+1)">下一页</button></view></template>
<template v-else-if="dialog==='delete'"><text class="delete-name">{{deleteTarget?.data.name}}</text><text class="hint">删除后无法恢复。导出的图片仍由你保留。</text><view class="start-actions"><button :disabled="deleting" @click="dialog='library'">先留着</button><button class="danger" :disabled="deleting||saving" @click="deleteWork">{{deleting?'正在收走…':'确认删除'}}</button></view></template>
<template v-else-if="dialog==='clear'"><text class="hint">只清空已放的豆子，参考图和作品名称保留。本次操作可以撤销。</text><view class="start-actions"><button @click="closeDialog">继续拼</button><button class="danger" @click="clearBoard">清空底板</button></view></template>
</view></view></view>
</template>
